function makeSeededTokioAdvancedDeathPolicy(
  productId: string,
  variantId: string,
  assuranceProfileOverrides: Partial<NonNullable<IlpPolicyInput['assuranceProfile']>> = {},
): IlpPolicyInput {
  const { manifest, products } = getIlpCatalog()
  const product = products.find((entry) => entry.id === productId)
  if (!product) {
    throw new Error(`Missing catalog product ${productId}`)
  }

  const variant = product.variants.find((entry) => entry.id === variantId)
  if (!variant) {
    throw new Error(`Missing catalog variant ${productId}/${variantId}`)
  }

  const seed = templateVariantToPolicySeed(product, variant, manifest)

  return ilpPolicySchema.parse({
    id: `${productId}-${variantId}`,
    ...seed,
    currentPolicyYear: 4,
    monthsAlreadyPaid: 36,
    funds: [ZERO_RETURN_FUND],
    accounts: seed.accounts.map((account) => ({
      ...account,
      currentValue: 0,
    })),
    assuranceProfile: {
      currentAgeNextBirthday: 40,
      sex: 'male',
      smokerStatus: 'non-smoker',
      currentNetRegularPremiumBase: 50_000,
      ...assuranceProfileOverrides,
    },
  })
}

