  it('keeps AIA Platinum Retirement Elite in force while premium-holiday charges are still covered and lapses after seeded account-value depletion', () => {
    const { manifest, products } = getIlpCatalog()
    const product = products.find((entry) => entry.id === 'aia-platinum-retirement-elite')
    expect(product).toBeDefined()

    const variant = product?.variants.find((entry) => entry.id === 'sgd-mip-5')
    expect(variant).toBeDefined()

    const seed = templateVariantToPolicySeed(product!, variant!, manifest)
    const buildPolicy = (currentValue: number) => ilpPolicySchema.parse({
      id: 'seeded-policy',
      ...seed,
      currentPolicyYear: 2,
      monthsAlreadyPaid: 12,
      funds: [ZERO_RETURN_FUND],
      accounts: seed.accounts.map((account) => ({
        ...account,
        currentValue,
      })),
      policyEvents: [
        {
          id: 'holiday-1',
          type: 'premium-holiday',
          startPolicyMonth: 13,
          durationMonths: 12,
          repayMissedPremiums: false,
        },
      ],
    })

    const inForcePolicy = buildPolicy(2_000)
    const depletedPolicy = buildPolicy(200)
    const inForceResult = projectIlpPolicy(inForcePolicy, 'mid')
    const depletedResult = projectIlpPolicy(depletedPolicy, 'mid')

    expect(inForcePolicy.policyStateSupport).toEqual(expect.objectContaining({
      automaticLapseOnAccountValueDepletion: true,
    }))
    expect(inForcePolicy.catalogSource?.modeledEconomics).toContain('kernel:automatic-lapse-on-account-depletion')
    expect(inForceResult.rows[0]?.policyState).toBe('in-force')
    expect(inForceResult.rows[0]?.annualContribution).toBe(0)
    expect(inForceResult.rows[0]?.combinedValue).toBeGreaterThan(0)

    expect(depletedResult.rows[0]?.policyState).toBe('in-force')
    expect(depletedResult.rows[0]?.annualContribution).toBe(0)
    expect(depletedResult.rows[0]?.combinedValue).toBe(0)
    expect(depletedResult.rows.slice(1).every((row) => row.policyState === 'lapsed')).toBe(true)
    expect(depletedResult.rows.slice(1).every((row) => row.annualContribution === 0)).toBe(true)
  })

