  it('disqualifies Wealth Builder@Future Power-up Bonus when an accumulation-account partial withdrawal occurs in the reference year', () => {
    const { manifest, products } = getIlpCatalog()
    const product = products.find((entry) => entry.id === 'tokio-marine-wealth-builder-atfuture')
    const variant = product?.variants.find((entry) => entry.id === 'sgd-mip-10')

    expect(product).toBeDefined()
    expect(variant).toBeDefined()

    const seed = templateVariantToPolicySeed(product!, variant!, manifest)
    const basePolicy = ilpPolicySchema.parse({
      id: 'tokio-marine-wealth-builder-atfuture-power-up-base',
      ...seed,
      currentPolicyYear: 9,
      monthsAlreadyPaid: 108,
      funds: [ZERO_RETURN_FUND],
      accounts: seed.accounts.map((account) => ({
        ...account,
        currentValue: account.id === 'accumulation' ? 10_000 : 0,
      })),
    })

    const gatedPolicy = ilpPolicySchema.parse({
      ...basePolicy,
      id: 'tokio-marine-wealth-builder-atfuture-power-up-gated',
      policyEvents: [
        {
          id: 'wbf-withdrawal',
          type: 'partial-withdrawal',
          label: 'Partial Withdrawal',
          startPolicyMonth: 110,
          durationMonths: 1,
          amount: 500,
          accountId: 'accumulation',
        },
      ],
    })

    const baseResult = projectIlpPolicy(basePolicy, 'mid')
    const gatedResult = projectIlpPolicy(gatedPolicy, 'mid')

    expect(accountRow(baseResult.rows[0], 'accumulation').bonusCredit).toBeGreaterThan(0)
    expect(accountRow(gatedResult.rows[0], 'accumulation').bonusCredit).toBe(0)
  })

