  it('represents Legacy Flex Solitaire Withdrawal Access Option withdrawals through event-level charge and loyalty waivers on the seeded product path', () => {
    const { manifest, products } = getIlpCatalog()
    const product = products.find((entry) => entry.id === 'income-legacy-flex-solitaire')
    expect(product).toBeDefined()

    const variant = product?.variants.find((entry) => entry.id === 'sgd-regular-mip-10')
    expect(variant).toBeDefined()

    const seed = templateVariantToPolicySeed(product!, variant!, manifest)
    const basePolicy = ilpPolicySchema.parse({
      id: 'seeded-policy',
      ...seed,
      currentPolicyYear: 9,
      monthsAlreadyPaid: 108,
      postMipYears: 2,
      monthlyContribution: 0,
      funds: [ZERO_RETURN_FUND],
      accounts: seed.accounts.map((account) => ({
        ...account,
        feeRate: 0,
        postMipFeeRate: null,
        currentValue: account.id === 'premium' ? 100_000 : 10_000,
      })),
      policyEvents: [
        {
          id: 'withdrawal-1',
          type: 'partial-withdrawal',
          startPolicyMonth: 115,
          durationMonths: 1,
          amount: 5_000,
          accountId: 'premium',
        },
      ],
    })

    const suspended = projectIlpPolicy(basePolicy, 'mid')
    const waived = projectIlpPolicy({
      ...basePolicy,
      policyEvents: [
        {
          ...basePolicy.policyEvents![0],
          chargeWaived: true,
          bonusSuspensionWaived: true,
        },
      ],
    }, 'mid')

    expect(basePolicy.catalogSource?.metadataOnlyBehaviors).toContain('income-legacy-flex-solitaire-withdrawal-access-option')
    expect(basePolicy.catalogWarnings?.some((warning) => warning.includes('Qualifying Withdrawal Access Option withdrawals can be represented in V1 with event-level charge and loyalty-bonus-suspension waivers'))).toBe(true)
    expect(accountRow(suspended.rows[0], 'premium').grossFee).toBeGreaterThan(accountRow(waived.rows[0], 'premium').grossFee)
    expect(accountRow(waived.rows[0], 'premium').grossFee).toBeCloseTo(0, 2)
    expect(accountRow(waived.rows[1], 'premium').bonusCredit).toBeGreaterThan(accountRow(suspended.rows[1], 'premium').bonusCredit)
    expect(accountRow(waived.rows[1], 'premium').bonusCredit).toBeGreaterThan(0)
  })

