  it('preserves Invest Flex loyalty-bonus basis after a qualifying Life Events withdrawal through the seeded preserved-value seam', () => {
    const { manifest, products } = getIlpCatalog()
    const product = products.find((entry) => entry.id === 'income-invest-flex')
    expect(product).toBeDefined()

    const variant = product?.variants.find((entry) => entry.id === 'sgd-mip-10')
    expect(variant).toBeDefined()

    const seed = templateVariantToPolicySeed(product!, variant!, manifest)
    const basePolicy = ilpPolicySchema.parse({
      id: 'seeded-policy',
      ...seed,
      currentPolicyYear: 7,
      monthsAlreadyPaid: 84,
      accounts: seed.accounts.map((account) => ({
        ...account,
        currentValue: 10_000,
      })),
    })
    const qualifyingWithdrawalPolicy = ilpPolicySchema.parse({
      id: 'seeded-policy',
      ...basePolicy,
      id: 'income-vs1-lewb-qualified',
      policyEvents: [
        {
          id: 'vs1-qualified-withdrawal',
          type: 'partial-withdrawal',
          startPolicyMonth: 85,
          durationMonths: 1,
          amount: 500,
          accountId: 'policy',
          chargeWaived: true,
          bonusSuspensionWaived: true,
        },
      ],
    })
    const ordinaryWithdrawalPolicy = ilpPolicySchema.parse({
      id: 'seeded-policy',
      ...basePolicy,
      id: 'income-vs1-ordinary-withdrawal',
      policyEvents: [
        {
          id: 'vs1-ordinary-withdrawal',
          type: 'partial-withdrawal',
          startPolicyMonth: 85,
          durationMonths: 1,
          amount: 500,
          accountId: 'policy',
        },
      ],
    })

    const baseProjection = projectIlpPolicy(basePolicy, 'mid')
    const qualifiedProjection = projectIlpPolicy(qualifyingWithdrawalPolicy, 'mid')
    const ordinaryProjection = projectIlpPolicy(ordinaryWithdrawalPolicy, 'mid')
    const baseProjectionWithoutBonus = projectIlpPolicy(withoutBonus(basePolicy, 'loyalty-bonus'), 'mid')
    const qualifiedProjectionWithoutBonus = projectIlpPolicy(withoutBonus(qualifyingWithdrawalPolicy, 'loyalty-bonus'), 'mid')
    const ordinaryProjectionWithoutBonus = projectIlpPolicy(withoutBonus(ordinaryWithdrawalPolicy, 'loyalty-bonus'), 'mid')
    const finalRowIndex = baseProjection.rows.length - 1

    expect(finalRowIndex).toBeGreaterThanOrEqual(2)

    const baseBonus = accountRow(baseProjection.rows[finalRowIndex]!, 'policy').bonusCredit
      - accountRow(baseProjectionWithoutBonus.rows[finalRowIndex]!, 'policy').bonusCredit
    const qualifiedBonus = accountRow(qualifiedProjection.rows[finalRowIndex]!, 'policy').bonusCredit
      - accountRow(qualifiedProjectionWithoutBonus.rows[finalRowIndex]!, 'policy').bonusCredit
    const ordinaryBonus = accountRow(ordinaryProjection.rows[finalRowIndex]!, 'policy').bonusCredit
      - accountRow(ordinaryProjectionWithoutBonus.rows[finalRowIndex]!, 'policy').bonusCredit

    expect(basePolicy.catalogSource?.modeledEconomics).toContain('kernel:bonus-preserved-value-cohorts')
    expect(basePolicy.bonuses.find((bonus) => bonus.id === 'loyalty-bonus')?.preservedValueRules).toEqual([
      {
        trigger: 'partial-withdrawal',
        basis: 'event-amount',
        accountIds: ['policy'],
        requiresBonusSuspensionWaived: true,
      },
    ])
    expect(qualifiedBonus).toBeCloseTo(baseBonus, 6)
    expect(ordinaryBonus).toBeLessThan(baseBonus)
  })

