  it('waives #goAssure partial-withdrawal and premium-shortfall charges on explicit approved events', () => {
    const { manifest, products } = getIlpCatalog()
    const product = products.find((entry) => entry.id === 'tokio-marine-goassure')
    const variant = product?.variants.find((entry) => entry.id === 'sgd-mip-10')

    expect(product).toBeDefined()
    expect(variant).toBeDefined()

    const seed = templateVariantToPolicySeed(product!, variant!, manifest)
    const basePolicy = ilpPolicySchema.parse({
      id: 'tokio-goassure-waiver-base',
      ...seed,
      currentPolicyYear: 4,
      monthsAlreadyPaid: 48,
      funds: [ZERO_RETURN_FUND],
      accounts: seed.accounts.map((account) => ({
        ...account,
        currentValue: account.id === 'accumulation'
          ? 10_000
          : (account.id === 'initial' ? 5_000 : 1_000),
      })),
      policyEvents: [
        {
          id: 'goassure-withdrawal',
          type: 'partial-withdrawal',
          label: 'Partial Withdrawal',
          startPolicyMonth: 49,
          durationMonths: 1,
          amount: 1_000,
          accountId: 'accumulation',
        },
        {
          id: 'goassure-holiday',
          type: 'premium-holiday',
          label: 'Premium Holiday',
          startPolicyMonth: 49,
          durationMonths: 3,
        },
        {
          id: 'goassure-reduction',
          type: 'regular-premium-reduction',
          label: 'Regular Premium Reduction',
          startPolicyMonth: 52,
          durationMonths: 1,
          amount: 1_200,
        },
      ],
    })
    const waivedPolicy = ilpPolicySchema.parse({
      ...basePolicy,
      id: 'tokio-goassure-waiver-approved',
      policyEvents: basePolicy.policyEvents?.map((event) => ({
        ...event,
        chargeWaived: true,
      })),
    })

    const charged = projectIlpPolicy(basePolicy, 'mid')
    const waived = projectIlpPolicy(waivedPolicy, 'mid')
    const chargedFee = accountRow(charged.rows[0], 'accumulation').grossFee
    const waivedFee = accountRow(waived.rows[0], 'accumulation').grossFee

    expect(chargedFee).toBeGreaterThan(waivedFee)
    expect(chargedFee - waivedFee).toBeGreaterThan(1_400)
    expect(waivedFee).toBe(0)
  })

