    const accepted = projectIlpPolicy(acceptedPolicy, 'mid')

    expect(blockedPolicy.catalogSource?.modeledEconomics).toContain('kernel:minimum-recurring-single-premium-amount')
    expect(blockedPolicy.policyStateSupport?.minimumRecurringSinglePremiumMonthlyAmount).toBe(50)
    expect(accountRow(blocked.rows[0], 'topup').contributionAmount).toBe(0)
    expect(accountRow(accepted.rows[0], 'topup').contributionAmount).toBe(600)
