  it('blocks Tiq Invest ad-hoc top-ups below the published SGD 500 minimum through the seeded product support seam', () => {
    const { manifest, products } = getIlpCatalog()
    const product = products.find((entry) => entry.id === 'etiqa-tiq-invest')
    expect(product).toBeDefined()

    const variant = product?.variants.find((entry) => entry.id === 'sgd-open-ended')
    expect(variant).toBeDefined()

    const seed = templateVariantToPolicySeed(product!, variant!, manifest)
    const policy = ilpPolicySchema.parse({
      id: 'seeded-policy',
      ...seed,
      currentPolicyYear: 2,
      monthsAlreadyPaid: 12,
      monthlyContribution: 0,
      accounts: seed.accounts.map((account) => ({
        ...account,
        currentValue: 10_000,
      })),
      policyEvents: [
        {
          id: 'tiq-below-minimum-top-up',
          type: 'top-up',
          startPolicyMonth: 13,
          durationMonths: 1,
          amount: 400,
        },
      ],
    })

    const result = projectIlpPolicy(policy, 'mid')

    expect(policy.catalogSource?.modeledEconomics).toContain('kernel:top-up-amount-gate-block')
    expect(policy.policyStateSupport).toMatchObject({
      minimumTopUpAmount: 500,
      topUpAmountIncrement: 100,
    })
    expect(result.rows[0]?.annualContribution).toBe(0)
    expect(accountRow(result.rows[0], 'policy').contributionAmount).toBe(0)
  })

