  it.each([
    ['tokio-marine-wealth-flexi-link-5-10', 'Wealth Flexi-Link 5.10', 'sgd-mip-10', 25, 13, 2, 12],
    ['tokio-marine-wealth-flexi-link-3-12', 'Wealth Flexi-Link 3.12', 'sgd-mip-12', 25, 13, 2, 12],
    ['tokio-marine-wealth-builder-atfuture', 'Wealth Builder@Future', 'sgd-mip-10', 25, 13, 2, 12],
    ['tokio-marine-harvest-builder-atfuture', 'Harvest Builder@Future', 'sgd-mip-10', 25, 13, 2, 12],
    ['tokio-marine-goaffluence', '#goAffluence', 'sgd-mip-15', 25, 13, 2, 12],
    ['tokio-marine-affluence-atfuture', 'Affluence@Future', 'sgd-mip-15', 25, 13, 2, 12],
    ['tokio-marine-atlas-wealth', 'TM Atlas Wealth', 'sgd-mip-25', 13, 1, 1, 0],
    ['tokio-marine-goluxe', '#goLuxe', 'sgd-mip-15', 37, 25, 3, 24],
  ])(
    'blocks %s premium-holiday events before policy month %i through the seeded product support seam',
    (productId, productName, variantId, minimumPremiumHolidayStartPolicyMonth, blockedHolidayStartMonth, currentPolicyYear, monthsAlreadyPaid) => {
      const { manifest, products } = getIlpCatalog()
      const product = products.find((entry) => entry.id === productId)
      expect(product).toBeDefined()

      const variant = product?.variants.find((entry) => entry.id === variantId)
      expect(variant).toBeDefined()

      const seed = templateVariantToPolicySeed(product!, variant!, manifest)
      const baseline = ilpPolicySchema.parse({
      id: 'seeded-policy',
        ...seed,
        currentPolicyYear,
        monthsAlreadyPaid,
        accounts: seed.accounts.map((account) => ({
          ...account,
          currentValue: 10_000,
        })),
      })
      const blockedHoliday = ilpPolicySchema.parse({
      id: 'seeded-policy',
        ...baseline,
        policyEvents: [
          {
            id: 'holiday-too-early',
            type: 'premium-holiday',
            startPolicyMonth: blockedHolidayStartMonth,
            durationMonths: 2,
          },
        ],
      })

      const baselineResult = projectIlpPolicy(baseline, 'mid')
      const blockedResult = projectIlpPolicy(blockedHoliday, 'mid')

      expect(blockedHoliday.policyStateSupport).toMatchObject({
        automaticLapseOnAccountValueDepletion: false,
        minimumPremiumHolidayStartPolicyMonth,
        requiresCommencementPremiumForRecurringSinglePremiumResumption: true,
      })
      expect(blockedHoliday.catalogSource?.modeledEconomics).toContain('kernel:minimum-premium-holiday-start-month')
      expect(blockedHoliday.catalogSource?.modeledEconomics).toContain('kernel:committed-premium-rsp-resumption-gate')
      expect(blockedResult.rows[0]?.annualContribution).toBe(seed.monthlyContribution * 12)
      expect(blockedResult.rows[0]?.annualContribution).toBe(baselineResult.rows[0]?.annualContribution)
      expect(
        blockedResult.rows[0]?.accounts.reduce((sum, account) => sum + account.grossFee, 0),
      ).toBeCloseTo(
        baselineResult.rows[0]?.accounts.reduce((sum, account) => sum + account.grossFee, 0) ?? 0,
        6,
      )
      expect(blockedHoliday.catalogSource?.productName).toBe(productName)
    },
  )

